export interface PanelSpec {
  key: string;
  title: string;
}

export interface FeatureManifest {
  imports: string[];
  providers: string[];
  routes: Array<{
    path: string;
    panelKey: string;
    metadata: { heading: string };
  }>;
}

function cleanText(value: string, name: string): string {
  if (typeof value !== "string" || value.trim().length === 0) {
    throw new TypeError(`${name} must contain non-whitespace text`);
  }
  return value.trim();
}

export function buildFeatureManifest(
  panel: PanelSpec,
  services: readonly string[]
): FeatureManifest {
  if (typeof panel !== "object" || panel === null || !Array.isArray(services)) {
    throw new TypeError("Invalid manifest input");
  }
  const key = cleanText(panel.key, "panel.key");
  const title = cleanText(panel.title, "panel.title");
  const providers = services.map((service) => cleanText(service, "service"));
  if (new Set(providers).size !== providers.length) {
    throw new Error("Duplicate service");
  }

  return {
    imports: ["foundation", "commands", "validation", "widgets"],
    providers: [...providers],
    routes: [{ path: key, panelKey: key, metadata: { heading: title } }]
  };
}

