import { buildFeatureManifest, PanelSpec } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function expectError(action: () => void, ctor: typeof Error, message: string): void {
  let caught: unknown;
  try { action(); } catch (error) { caught = error; }
  assert(caught instanceof ctor, message);
}

const panel: PanelSpec = { key: "  reports  ", title: "  Sales Report  " };
const services = [" auth ", "billing", " notifications "];
const manifest = buildFeatureManifest(panel, services);
assert(manifest.imports.join(",") === "foundation,commands,validation,widgets", "imports have the required order");
assert(manifest.providers.join(",") === "auth,billing,notifications", "providers are trimmed and preserve order");
assert(manifest.routes.length === 1, "manifest has exactly one route");
assert(manifest.routes[0].path === "", "route path is empty");
assert(manifest.routes[0].panelKey === "reports", "panel key is trimmed");
assert(manifest.routes[0].metadata.heading === "Sales Report", "heading is the trimmed title");
assert(panel.key === "  reports  " && panel.title === "  Sales Report  ", "panel input is not mutated");
assert(services.join("|") === " auth |billing| notifications ", "services input is not mutated");

const another = buildFeatureManifest(panel, services);
assert(another !== manifest, "each manifest is new");
assert(another.imports !== manifest.imports && another.providers !== manifest.providers, "manifest arrays are newly allocated");
assert(another.routes !== manifest.routes && another.routes[0] !== manifest.routes[0], "route structures are newly allocated");
assert(another.routes[0].metadata !== manifest.routes[0].metadata, "metadata is newly allocated");
manifest.imports.push("changed");
manifest.providers[0] = "changed";
manifest.routes[0].metadata.heading = "changed";
assert(another.imports.length === 4 && another.providers[0] === "auth" && another.routes[0].metadata.heading === "Sales Report", "outputs do not alias each other");

const noServices = buildFeatureManifest({ key: "k", title: "T" }, []);
assert(noServices.providers.length === 0, "empty services are valid");

for (const bad of ["", "   ", 3, null]) {
  expectError(() => buildFeatureManifest({ key: bad as string, title: "Title" }, []), TypeError, "malformed key throws TypeError");
  expectError(() => buildFeatureManifest({ key: "key", title: bad as string }, []), TypeError, "malformed title throws TypeError");
  expectError(() => buildFeatureManifest({ key: "key", title: "Title" }, [bad as string]), TypeError, "malformed service throws TypeError");
}
expectError(() => buildFeatureManifest({ key: "key", title: "Title" }, ["api", " api "]), Error, "duplicates after trimming throw Error");

